import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping the high bits around.

    x is an int in 0..255 and k is an int in 0..7. The result is in 0..255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_zero_shift_is_identity() -> None:
    for x in (0, 1, 0x55, 0x80, 0xFF):
        assert rotl8(x, 0) == x


def test_rotl8_simple_shift_without_wrap() -> None:
    assert rotl8(0b00000001, 3) == 0b00001000
    assert rotl8(0b00010110, 2) == 0b01011000


def test_rotl8_wraps_high_bits() -> None:
    assert rotl8(0b10000000, 1) == 0b00000001
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(0b11000000, 2) == 0b00000011
    assert rotl8(0b00000001, 7) == 0b10000000


def test_rotl8_nibble_swap() -> None:
    assert rotl8(0xA5, 4) == 0x5A
    assert rotl8(0x12, 4) == 0x21


def test_rotl8_all_zeros_and_all_ones() -> None:
    for k in range(8):
        assert rotl8(0x00, k) == 0x00
        assert rotl8(0xFF, k) == 0xFF


def test_rotl8_result_in_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255


def test_rotl8_matches_reference_exhaustively() -> None:
    for x in range(256):
        for k in range(8):
            bits = format(x, "08b")
            expected = int(bits[k:] + bits[:k], 2)
            assert rotl8(x, k) == expected


def test_rotl8_preserves_popcount() -> None:
    for x in range(256):
        for k in range(8):
            assert bin(rotl8(x, k)).count("1") == bin(x).count("1")


def test_rotl8_inverse_with_complementary_shift() -> None:
    for x in range(256):
        for k in range(8):
            assert rotl8(rotl8(x, k), (8 - k) % 8) == x


@pytest.mark.parametrize(
    ("x", "k", "expected"),
    [
        (0x01, 0, 0x01),
        (0x01, 1, 0x02),
        (0x81, 1, 0x03),
        (0xF0, 4, 0x0F),
        (0x0F, 4, 0xF0),
        (0x80, 7, 0x40),
        (0xFE, 7, 0x7F),
    ],
)
def test_rotl8_examples(x: int, k: int, expected: int) -> None:
    assert rotl8(x, k) == expected

